37: namespace {
38: // This is an approximation of time between frames, used when ticking the
39: // animation clock outside of animation frame callbacks.
40: constexpr base::TimeDelta kApproximateFrameTime = base::Seconds(1 / 60.0);
41: }  // namespace
42: 
43: unsigned AnimationClock::currently_running_task_ = 0;
44: 
45: void AnimationClock::UpdateTime(base::TimeTicks time) {
46:   task_for_which_time_was_calculated_ = currently_running_task_;
47: 
48:   // TODO(crbug.com/985770): Change this to a DCHECK_GE(time, time_) when
49:   // VR no longer sends historical timestamps.
50:   if (time < time_)
51:     return;
52:   time_ = time;
53: }
54: 
55: base::TimeTicks AnimationClock::CurrentTime() {
56:   // By spec, within a single rendering lifecycle the AnimationClock time should
57:   // not change (as it is set from the frame time).
58:   if (!can_dynamically_update_time_)
59:     return time_;
60: 
61:   // Outside of the rendering lifecycle, we may have to dynamically advance our
62:   // own time (see comments on |SetAllowedToDynamicallyUpdateTime|). However we
63:   // should never dynamically advance time inside a single task, as otherwise a
64:   // single long-running JavaScript function could see multiple different times
65:   // from document.timeline.currentTime.
66:   if (task_for_which_time_was_calculated_ == currently_running_task_)
67:     return time_;
68: 
69:   // Otherwise, we may need to dynamically update our own time. Again see the
70:   // comments on |SetAllowedToDynamicallyUpdateTime|.
71:   const base::TimeTicks current_time = clock_->NowTicks();
72:   base::TimeTicks new_time = time_;
73: 
74:   // TODO(crbug.com/1497922) timestamps outside rendering updates should be
75:   // coarsened.
76:   if (time_ < current_time) {
77:     // Attempt to predict what the most recent timestamp would have been. This
78:     // may not produce a result greater than |time_|, but it greatly reduces the
79:     // chance of conflicting with any future frame timestamp that does come in.
80:     const base::TimeDelta frame_shift =
81:         (current_time - time_) % kApproximateFrameTime;
82:     new_time = current_time - frame_shift;
83:     DCHECK_GE(new_time, time_);
84:   }
85:   UpdateTime(new_time);
86: 
87:   return time_;
88: }
89: 
90: void AnimationClock::ResetTimeForTesting() {
91:   time_ = base::TimeTicks();
92: }
