47: // Returns the current animation time for a given |document|. This is
48: // the animation clock time capped to be at least this document's
49: // CalculateZeroTime() such that the animation time is never negative when
50: // converted.
51: base::TimeTicks CurrentAnimationTime(Document* document) {
52:   base::TimeTicks animation_time = document->GetAnimationClock().CurrentTime();
53:   base::TimeTicks document_zero_time = document->Timeline().CalculateZeroTime();
54: 
55:   // The AnimationClock time may be null or less than the local document's
56:   // zero time if we have not generated any frames for this document yet. If
57:   // so, assume animation_time is the document zero time.
58:   if (animation_time < document_zero_time)
59:     return document_zero_time;
60: 
61:   return animation_time;
62: }
