111: void DocumentTimeline::ScheduleNextService() {
112:   DCHECK_EQ(outdated_animation_count_, 0U);
113: 
114:   std::optional<AnimationTimeDelta> time_to_next_effect;
115:   for (const auto& animation : animations_needing_update_) {
116:     std::optional<AnimationTimeDelta> time_to_effect_change =
117:         animation->TimeToEffectChange();
118:     if (!time_to_effect_change)
119:       continue;
120: 
121:     time_to_next_effect = time_to_next_effect
122:                               ? std::min(time_to_next_effect.value(),
123:                                          time_to_effect_change.value())
124:                               : time_to_effect_change.value();
125:   }
126: 
127:   if (!time_to_next_effect)
128:     return;
129:   double next_effect_delay = time_to_next_effect.value().InSecondsF();
130:   if (next_effect_delay < kMinimumDelay) {
131:     ScheduleServiceOnNextFrame();
132:   } else {
133:     timing_->WakeAfter(base::Seconds(next_effect_delay - kMinimumDelay));
134:   }
135: }
