100: bool AnimationTimeline::NeedsAnimationTimingUpdate() {
101:   PhaseAndTime current_phase_and_time = CurrentPhaseAndTime();
102:   if (current_phase_and_time == last_current_phase_and_time_)
103:     return false;
104: 
105:   // We allow |last_current_phase_and_time_| to advance here when there
106:   // are no animations to allow animations spawned during style
107:   // recalc to not invalidate this flag.
108:   if (animations_needing_update_.empty()) {
109:     last_current_phase_and_time_ = current_phase_and_time;
110:     // Make sure triggers get the chance to respond to the updated PhaseAndTime.
111:     update_triggers_ = true;
112:   }
113: 
114:   return !animations_needing_update_.empty();
115: }
