117: void AnimationTimeline::ServiceAnimations(TimingUpdateReason reason) {
118:   TRACE_EVENT0("blink", "AnimationTimeline::serviceAnimations");
119: 
120:   auto current_phase_and_time = CurrentPhaseAndTime();
121: 
122:   if (IsProgressBased()) {
123:     if (last_current_phase_and_time_ != current_phase_and_time) {
124:       UpdateCompositorTimeline();
125:     }
126:   }
127: 
128:   last_current_phase_and_time_ = current_phase_and_time;
129: 
130:   HeapVector<Member<Animation>> animations;
131:   animations.ReserveInitialCapacity(animations_needing_update_.size());
132:   for (Animation* animation : animations_needing_update_)
133:     animations.push_back(animation);
134: 
135:   std::sort(animations.begin(), animations.end(), CompareAnimations);
136: 
137:   for (Animation* animation : animations) {
138:     if (!animation->Update(reason))
139:       animations_needing_update_.erase(animation);
140:   }
141: 
142:   DCHECK_EQ(outdated_animation_count_, 0U);
143:   DCHECK(last_current_phase_and_time_ == CurrentPhaseAndTime());
144: 
145: #if DCHECK_IS_ON()
146:   for (const auto& animation : animations_needing_update_)
147:     DCHECK(!animation->Outdated());
148: #endif
149:   // Explicitly free the backing store to avoid memory regressions.
150:   // TODO(bikineev): Revisit when young generation is done.
151:   animations.clear();
152: }
