120: export function serverTailPolicy() {
121:   const alphaPerTail = SERVER_PROFILE.familyAlpha / (SERVER_PROFILE.familySize * 2 * 2 * 2);
122:   return { alphaPerTail, quantiles: [0.5, 0.95], minimumBlocks: Math.ceil(Math.log(alphaPerTail) / Math.log(0.95)),
123:     correction: 'Bonferroni: 10 cells × 2 quantiles × 2 participants × 2 tails; family-wise 95%' };
124: }
