78: namespace subtle {
79: Time TimeNowIgnoringOverride() {
80:   struct timeval tv;
81:   struct timezone tz = {0, 0};  // UTC
82:   CHECK(gettimeofday(&tv, &tz) == 0);
83:   // Combine seconds and microseconds in a 64-bit field containing microseconds
84:   // since the epoch.  That's enough for nearly 600 centuries.  Adjust from
85:   // Unix (1970) to Windows (1601) epoch.
86:   return Time() +
87:          Microseconds((tv.tv_sec * Time::kMicrosecondsPerSecond + tv.tv_usec) +
88:                       Time::kTimeTToMicrosecondsOffset);
89: }
