113: // CPUUsage use libuv's uv_getrusage() this-process resource usage accessor,
114: // to access ru_utime (user CPU time used) and ru_stime (system CPU time used),
115: // which are uv_timeval_t structs (long tv_sec, long tv_usec).
116: // Returns those values as Float64 microseconds in the elements of the array
117: // passed to the function.
118: static void CPUUsage(const FunctionCallbackInfo<Value>& args) {
119:   Environment* env = Environment::GetCurrent(args);
120:   uv_rusage_t rusage;
121: 
122:   // Call libuv to get the values we'll return.
123:   int err = uv_getrusage(&rusage);
124:   if (err)
125:     return env->ThrowUVException(err, "uv_getrusage");
126: 
127:   // Get the double array pointer from the Float64Array argument.
128:   Local<ArrayBuffer> ab = get_fields_array_buffer(args, 0, 2);
129:   double* fields = static_cast<double*>(ab->Data());
130: 
131:   // Set the Float64Array elements to be user / system values in microseconds.
132:   fields[0] = MICROS_PER_SEC * rusage.ru_utime.tv_sec + rusage.ru_utime.tv_usec;
133:   fields[1] = MICROS_PER_SEC * rusage.ru_stime.tv_sec + rusage.ru_stime.tv_usec;
134: }
