136: // ThreadCPUUsage use libuv's uv_getrusage_thread() this-thread resource usage
137: // accessor, to access ru_utime (user CPU time used) and ru_stime
138: // (system CPU time used), which are uv_timeval_t structs
139: // (long tv_sec, long tv_usec).
140: // Returns those values as Float64 microseconds in the elements of the array
141: // passed to the function.
142: static void ThreadCPUUsage(const FunctionCallbackInfo<Value>& args) {
143:   Environment* env = Environment::GetCurrent(args);
144:   uv_rusage_t rusage;
145: 
146:   // Call libuv to get the values we'll return.
147:   int err = uv_getrusage_thread(&rusage);
