149: 
150:   // Get the double array pointer from the Float64Array argument.
151:   Local<ArrayBuffer> ab = get_fields_array_buffer(args, 0, 2);
152:   double* fields = static_cast<double*>(ab->Data());
153: 
154:   // Set the Float64Array elements to be user / system values in microseconds.
155:   fields[0] = MICROS_PER_SEC * rusage.ru_utime.tv_sec + rusage.ru_utime.tv_usec;
156:   fields[1] = MICROS_PER_SEC * rusage.ru_stime.tv_sec + rusage.ru_stime.tv_usec;
